import { readFileSync } from "node:fs";

/**
 * Minimal RFC-4180-style CSV parser (handles quoted fields with commas and
 * escaped quotes). The project data is machine-generated by cricsheet, but
 * venue names contain commas, so a naive split would corrupt rows.
 */
export function parseCsv(text) {
  const rows = [];
  let field = "";
  let row = [];
  let inQuotes = false;

  for (let i = 0; i < text.length; i += 1) {
    const ch = text[i];
    if (inQuotes) {
      if (ch === '"') {
        if (text[i + 1] === '"') {
          field += '"';
          i += 1;
        } else {
          inQuotes = false;
        }
      } else {
        field += ch;
      }
      continue;
    }

    if (ch === '"') {
      inQuotes = true;
    } else if (ch === ",") {
      row.push(field);
      field = "";
    } else if (ch === "\n") {
      row.push(field);
      rows.push(row);
      field = "";
      row = [];
    } else if (ch !== "\r") {
      field += ch;
    }
  }

  if (field.length > 0 || row.length > 0) {
    row.push(field);
    rows.push(row);
  }
  return rows;
}

/** Reads a CSV file into an array of plain objects keyed by the header row. */
export function readCsvObjects(path) {
  const text = readFileSync(path, "utf8").replace(/^\uFEFF/, "");
  const [header, ...rows] = parseCsv(text);
  const keys = header.map((h) => h.trim());
  return rows
    .filter((r) => r.length > 1 || (r.length === 1 && r[0] !== ""))
    .map((r) => {
      const obj = {};
      for (let i = 0; i < keys.length; i += 1) obj[keys[i]] = r[i] ?? "";
      return obj;
    });
}

export function num(value) {
  const n = Number(value);
  return Number.isFinite(n) ? n : 0;
}

export function round(value, dp = 2) {
  const f = 10 ** dp;
  return Math.round((value + Number.EPSILON) * f) / f;
}

/** SQL ROUND(x, dp) equivalent for comparisons against results/*.csv. */
export function close(actual, expected, dp = 2, tolerance = 0.5 * 10 ** -dp) {
  return Math.abs(actual - expected) <= tolerance + 1e-9;
}
